policies.inbound:












                Bearer error="invalid_token"






<set-variable name="userRoles" value="@{
    try {
        string tokenJson = context.Variables.GetValueOrDefault("accessToken");
        if (string.IsNullOrEmpty(tokenJson)) {
            return new JArray();
        }

        JObject tokenData = JObject.Parse(tokenJson);
        string accessTokenStr = tokenData["access_token"]?.ToString();

        if (string.IsNullOrEmpty(accessTokenStr)) {
            return new JArray();
        }

        // Parse JWT token to extract roles (from the payload section)
        string[] tokenParts = accessTokenStr.Split('.');
        if (tokenParts.Length < 2) {
            return new JArray();
        }

        // Decode the payload (second part of JWT)
        string payload = tokenParts[1];
        // Add padding if needed for base64 decoding
        int padding = 4 - (payload.Length % 4);
        if (padding < 4) {
            payload += new string('=', padding);
        }

        byte[] payloadBytes = Convert.FromBase64String(payload.Replace('-', '+').Replace('_', '/'));
        string payloadJson = Encoding.UTF8.GetString(payloadBytes);
        JObject payloadObj = JObject.Parse(payloadJson);

        // Extract roles from token (support both 'roles' and 'groups' claims)
        JArray roles = new JArray();
        HashSet uniqueRoles = new HashSet();

        // Check 'roles' claim (common in Entra ID app roles)
        if (payloadObj["roles"] != null) {
            foreach (var role in payloadObj["roles"]) {
                string roleStr = role.ToString();
                if (!string.IsNullOrEmpty(roleStr)) {
                    uniqueRoles.Add(roleStr);
                }
            }
        }

        // Also check 'groups' claim (Entra ID group memberships)
        // Combine both claims to support flexible role assignment
        if (payloadObj["groups"] != null) {
            foreach (var group in payloadObj["groups"]) {
                string groupStr = group.ToString();
                if (!string.IsNullOrEmpty(groupStr)) {
                    uniqueRoles.Add(groupStr);
                }
            }
        }

        // Convert unique roles to JArray
        foreach (var role in uniqueRoles) {
            roles.Add(role);
        }

        // If no roles found, assign default 'user' role
        if (roles.Count == 0) {
            roles.Add("user");
        }

        return roles;
    } catch (Exception ex) {
        // On error, return default 'user' role
        JArray defaultRoles = new JArray();
        defaultRoles.Add("user");
        return defaultRoles;
    }
}" />





<set-variable name="allowedTools" value="@{
    JArray userRoles = context.Variables.GetValueOrDefault("userRoles");
    JObject roleToolMapping = context.Variables.GetValueOrDefault("roleToolMapping");

    // Collect all allowed tools from all user roles (union of permissions)
    HashSet allowedToolsSet = new HashSet();

    foreach (var role in userRoles) {
        string roleName = role.ToString();
        if (roleToolMapping[roleName] != null) {
            JArray toolsForRole = (JArray)roleToolMapping[roleName];
            foreach (var tool in toolsForRole) {
                allowedToolsSet.Add(tool.ToString());
            }
        }
    }

    // Convert to JArray for easy access
    JArray allowedToolsArray = new JArray();
    foreach (var tool in allowedToolsSet) {
        allowedToolsArray.Add(tool);
    }

    return allowedToolsArray;
}" />



    @(context.Variables.GetValueOrDefault("allowedTools").ToString(Newtonsoft.Json.Formatting.None))





        <set-variable name="requestBody" value="@(context.Request.Body.As(preserveContent: true))" />
        <set-variable name="requestData" value="@{
            try {
                string body = context.Variables.GetValueOrDefault("requestBody");
                if (string.IsNullOrEmpty(body)) {
                    return null;
                }
                return JObject.Parse(body);
            } catch {
                return null;
            }
        }" />

        <set-variable name="requestMethod" value="@{
            JObject request = context.Variables.GetValueOrDefault("requestData");
            return request?["method"]?.ToString() ?? "";
        }" />

        <set-variable name="requestId" value="@{
            JObject request = context.Variables.GetValueOrDefault("requestData");
            return request?["id"]?.ToString() ?? "unknown";
        }" />



            <when condition="@(context.Variables.GetValueOrDefault("requestMethod") == "tools/call")">
                <set-variable name="requestedTool" value="@{
                    JObject request = context.Variables.GetValueOrDefault("requestData");
                    return request?["params"]?["name"]?.ToString() ?? "";
                }" />

                <set-variable name="isToolAllowed" value="@{
                    string requestedTool = context.Variables.GetValueOrDefault("requestedTool");
                    JArray allowedTools = context.Variables.GetValueOrDefault("allowedTools");

                    if (string.IsNullOrEmpty(requestedTool)) {
                        return false;
                    }

                    foreach (var tool in allowedTools) {
                        if (tool.ToString() == requestedTool) {
                            return true;
                        }
                    }
                    return false;
                }" />



                    <when condition="@(!context.Variables.GetValueOrDefault("isToolAllowed"))">



                                application/json

                            @{
                                string requestedTool = context.Variables.GetValueOrDefault("requestedTool");
                                string requestId = context.Variables.GetValueOrDefault("requestId");
                                JArray userRoles = context.Variables.GetValueOrDefault("userRoles");

                                JObject error = new JObject();
                                error["jsonrpc"] = "2.0";
                                error["id"] = requestId;  // Use actual request ID for proper correlation
                                error["error"] = new JObject();
                                error["error"]["code"] = -32001;
                                error["error"]["message"] = $"Access denied: Tool '{requestedTool}' is not available for your role(s): {userRoles.ToString(Newtonsoft.Json.Formatting.None)}";

                                return error.ToString();
                            }









    {{function-host-key}}
